ixelColor(i, strip.Color(0, 0, 0));  // Switching off inactive LEDs\n    }\n  }\n  strip.show();\n\n  delay(100);\n}\n'})}),"\n",(0,r.jsx)(a.h3,{id:"personaliza\xe7\xe3o",children:"Personaliza\xe7\xe3o"}),"\n",(0,r.jsx)(a.p,{children:"Voc\xea pode personalizar o comportamento da faixa NeoPixel reativa ao \xe1udio modificando os seguintes par\xe2metros:"}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.code,{children:"DELAYVAL"}),": O tempo de atraso (em milissegundos) entre cada atualiza\xe7\xe3o de pixel (padr\xe3o: 500)\n",(0,r.jsx)(a.code,{children:"Mapping range for activeLEDs"}),": Ajuste a faixa de valores de intensidade m\xe9dia para mapear para o n\xfamero de LEDs ativos (padr\xe3o: 30000 a 36000)\n",(0,r.jsx)(a.code,{children:"Color scheme"}),": Modifique a fun\xe7\xe3o strip.setPixelColor() para alterar a transi\xe7\xe3o de cor ou usar cores diferentes para os LEDs"]})]})}function p(e={}){let{wrapper:a}={...(0,o.R)(),...e.components};return a?(0,r.jsx)(a,{...e,children:(0,r.jsx)(c,{...e})}):c(e)}},71184(e,a,i){i.d(a,{R:()=>s,x:()=>t});var n=i(14041);let r={},o=n.createContext(r);function s(e){let a=n.useContext(o);return n.useMemo(function(){return"function"==typeof e?e(a):{...a,...e}},[a,e])}function t(e){let a;return a=e.disableParentContext?"function"==typeof e.components?e.components(r):e.components||r:s(e.components),n.createElement(o.Provider,{value:a},e.children)}}}]);